const staticData = $getWorkflowStaticData('global');
const before = (staticData.seenUrls || []).length;
staticData.seenUrls = [];
staticData.seenTimestamps = {};
console.log(`Очищено ${before} URL из истории дедупликации.`);
return [{ json: { cleared: before, message: `Очищено ${before} URL. Теперь можно тестировать воркфлоу заново — все вакансии снова будут видны как новые.` } }];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const maxLockMs = 30 * 60 * 1000; // страховка на случай, если release почему-то не выполнится

if (staticData.lockUntil && staticData.lockUntil > now) {
  console.log('Предыдущий запуск ещё выполняется — пропускаю этот триггер.');
  return [];
}

staticData.lockUntil = now + maxLockMs;
return [{ json: { _lockAcquired: true } }];

const staticData = $getWorkflowStaticData('global');
delete staticData.lockUntil;
console.log('Лок снят.');
return [{ json: { _released: true } }];

// geoId известен только для части стран (проверено вручную через linkedin.com/jobs).
// Для них шлём числовой geoId — он однозначный и не зависит от текстового резолвинга LinkedIn.
// Для остальных стран пока остаётся текстовый location (риск коллизии с одноимёнными
// населёнными пунктами США сохраняется, но фильтр 🌍 Country + Remote Filter всё равно
// отсеет мусор по итоговой локации вакансии).
const countryGeoIds = {
  Spain: '105646813',
  Netherlands: '102890719',
};

const countries = [
  'Netherlands','Spain','Armenia'
// Russia исключена: LinkedIn заблокирован в РФ с 2016, гостевой поиск отдаёт
// почти сплошной геомусор (левые вакансии из США/UK с фейковым 'Russia' в конце
// строки локации) вместо реальных местных вакансий — не лечится фильтром,
// т.к. мусор оканчивается тем же словом, что и настоящие совпадения.
];

// Гостевой эндпоинт LinkedIn отдаёт максимум ~10 карточек за запрос и требует
// явной пагинации через start (0, 10, 20...) — раньше запрашивалась только
// первая страница, из-за чего по каждой стране мы видели лишь первые 10
// вакансий вообще, до всех фильтров. Берём 3 страницы на страну (0/10/20).
const startOffsets = ['0', '10', '20'];

const out = [];
for (const c of countries) {
  for (const start of startOffsets) {
    out.push({ json: { country: c, geoId: countryGeoIds[c] || null, start } });
  }
}
return out;

// Разбор HTML-фрагмента гостевого поиска LinkedIn.
// ВНИМАНИЕ: вёрстка не документирована и может измениться —
// если после реального прогона парсинг даст 0 вакансий,
// нужно посмотреть на реальный HTML в поле "data" на входе этой ноды
// и поправить регулярки ниже под актуальную структуру.

const clean = s => (s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&nbsp;/g, ' ')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const blockedSignals = /authwall|challenge|captcha|Sign in to LinkedIn/i;

const results = [];
const errors = [];

for (const item of $input.all()) {
  const country = item.json.country || 'UNKNOWN';
  const html = item.json.data || item.json.body || '';
  const text = typeof html === 'string' ? html : JSON.stringify(html);

  if (!text || text.length < 300) {
    errors.push({ country, reason: 'Пустой или слишком короткий ответ (возможна блокировка)' });
    continue;
  }
  if (blockedSignals.test(text)) {
    errors.push({ country, reason: 'Похоже на authwall/капчу — LinkedIn мог заблокировать запрос' });
    continue;
  }

  const cardRegex = /<li>\s*<div class="base-card[\s\S]*?data-entity-urn="urn:li:jobPosting:(\d+)"[\s\S]*?<\/div>\s*<\/li>/g;
  let m;
  let foundInCountry = 0;
  while ((m = cardRegex.exec(text)) !== null) {
    const cardHtml = m[0];
    const jobId = m[1];

    const titleMatch = cardHtml.match(/base-search-card__title[^>]*>([\s\S]*?)<\/h3>/);
    const companyMatch = cardHtml.match(/base-search-card__subtitle[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/);
    const locationMatch = cardHtml.match(/job-search-card__location[^>]*>([\s\S]*?)<\/span>/);
    const urlMatch = cardHtml.match(/href="(https:\/\/[a-zA-Z0-9-]+\.linkedin\.com\/jobs\/view\/[^"?]+)/);
    const timeMatch = cardHtml.match(/datetime="([^"]+)"/);

    const job = {
      job_id: jobId,
      title: clean(titleMatch && titleMatch[1]),
      company: clean(companyMatch && companyMatch[1]),
      location: clean(locationMatch && locationMatch[1]),
      url: urlMatch ? urlMatch[1] : '',
      created: timeMatch ? timeMatch[1] : '',
      query_country: country,
      source: 'LinkedIn'
    };

    if (job.job_id && job.title && job.url) {
      results.push({ json: job });
      foundInCountry++;
    }
  }
  console.log(`LinkedIn [${country}]: найдено вакансий — ${foundInCountry}`);
}

if (errors.length > 0) {
  console.log('Проблемы по странам:', JSON.stringify(errors));
}

if (results.length === 0) {
  return [{ json: { _error: true, _reason: `LinkedIn: 0 вакансий распарсено. Проблемы: ${JSON.stringify(errors.slice(0, 5))}` } }];
}

return results;

const targetCountries = /\b(Austria|Belgium|Bulgaria|Croatia|Cyprus|Czech(?:ia| Republic)|Denmark|Estonia|Finland|France|Germany|Greece|Hungary|Ireland|Italy|Latvia|Lithuania|Luxembourg|Malta|Netherlands|Poland|Portugal|Romania|Slovakia|Slovenia|Spain|Sweden|Russia|Armenia)$/i;
const remoteSignal = /remote/i;

const out = [];
for (const item of $input.all()) {
  const job = item.json;
  if (job._error) { out.push(item); continue; }

  const location = (job.location || '').trim();
  const segments = location.split(',').map(s => s.trim()).filter(Boolean);
  const lastSegmentRaw = segments[segments.length - 1] || '';
  // LinkedIn часто пишет формат "Spain (Remote)" одним сегментом —
  // сначала проверяем remote-сигнал по ВСЕЙ строке локации, потом
  // отрезаем "(...)" и сверяем страну по чистому остатку.
  const lastSegment = lastSegmentRaw.replace(/\s*\([^)]*\)\s*$/, '').trim();

  const countryOk = targetCountries.test(lastSegment);
  // Явное слово "remote" — либо в заголовке вакансии, либо в самой локации.
  // Без этой проверки f_WT=2 пропускает и офисные вакансии (проверено на
  // реальных данных — врач-психиатр без единого упоминания remote).
  const remoteOk = remoteSignal.test(job.title || '') || remoteSignal.test(location);

  if (countryOk && remoteOk) {
    job._error = false;
    out.push(item);
  }
}
return out;

const allItemsRaw = $input.all();

if (allItemsRaw.length === 1 && allItemsRaw[0].json._error) {
  return [allItemsRaw[0]];
}

const staticData = $getWorkflowStaticData('global');

if (!staticData.seenUrls) staticData.seenUrls = [];
if (!staticData.seenTimestamps) staticData.seenTimestamps = {};

const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
Object.keys(staticData.seenTimestamps).forEach(url => {
  if (staticData.seenTimestamps[url] < thirtyDaysAgo) {
    delete staticData.seenTimestamps[url];
    const idx = staticData.seenUrls.indexOf(url);
    if (idx > -1) staticData.seenUrls.splice(idx, 1);
  }
});

const newJobs = allItemsRaw.filter(item => {
  const url = item.json.url;
  return url && !staticData.seenUrls.includes(url);
});

// Лог по источникам
const bySource = {};
newJobs.forEach(item => {
  const src = item.json.source || 'Unknown';
  bySource[src] = (bySource[src] || 0) + 1;
});
console.log(`Total: ${allItemsRaw.length} | New: ${newJobs.length} | Already seen: ${allItemsRaw.length - newJobs.length}`);
console.log('New by source:', JSON.stringify(bySource));

if (newJobs.length === 0) {
  return [{ json: { _noNewJobs: true } }];
}

return newJobs;

const real = $input.all().filter(item => !!item.json.url);

if (real.length === 0) {
  return [{ json: { _noNewJobs: true } }]; // маркер, чтобы дойти до release, даже если новых вакансий нет
}

real.forEach(item => { item.json._noNewJobs = false; });
return real;

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = [];
if (!staticData.seenTimestamps) staticData.seenTimestamps = {};

const results = [];
for (const item of $input.all()) {
  const job = item.json;
  if (job.url && !staticData.seenUrls.includes(job.url)) {
    staticData.seenUrls.push(job.url);
    staticData.seenTimestamps[job.url] = Date.now();
  }
  results.push(item);
}
return results;

const jobs = $input.all().map(item => item.json);

// Лимиты Discord: до 10 embed на сообщение, до ~4096 символов в description одного embed.
// Берём с запасом, чтобы не упереться в лимит на длинных названиях/локациях.
const JOBS_PER_EMBED = 15;
const EMBEDS_PER_MESSAGE = 5; // до 75 вакансий на одно Discord-сообщение

function jobLine(job) {
  const title = (job.title || 'Без названия').replace(/[\[\]]/g, '');
  const company = job.company || '—';
  const location = job.location || '—';
  return `• [${title}](${job.url}) — ${company}, ${location}`;
}

const embeds = [];
for (let i = 0; i < jobs.length; i += JOBS_PER_EMBED) {
  const chunk = jobs.slice(i, i + JOBS_PER_EMBED);
  const embed = {
    description: chunk.map(jobLine).join('\n').substring(0, 4000),
    color: 5763719
  };
  if (i === 0) embed.title = `🆕 Новые вакансии LinkedIn (${jobs.length})`;
  embeds.push(embed);
}
if (embeds.length > 0) {
  embeds[embeds.length - 1].footer = { text: `LinkedIn (гостевой поиск) • Remote • ${new Date().toLocaleDateString('ru-RU')}` };
}

const messages = [];
for (let i = 0; i < embeds.length; i += EMBEDS_PER_MESSAGE) {
  messages.push({ json: { discord_payload: { embeds: embeds.slice(i, i + EMBEDS_PER_MESSAGE) } } });
}

return messages;

const staticData = $getWorkflowStaticData('global');
staticData.aiKeptJobs = []; // сброс на случай, если прошлый прогон прервался посреди AI-цикла

const items = $input.all();
const CHUNK_SIZE = 15; // с запасом под лимит Groq free-tier (8000 TPM в минуту)
const chunks = [];
for (let i = 0; i < items.length; i += CHUNK_SIZE) {
  const slice = items.slice(i, i + CHUNK_SIZE);
  const jobsForAi = slice.map((it, idx) => ({ id: idx, title: it.json.title, company: it.json.company, location: it.json.location }));
  chunks.push({ json: { _jobsForAi: jobsForAi, _originalJobs: slice.map(it => it.json) } });
}
return chunks;

const resp = $json;
const originalJobs = $('🔁 AI Rate Limiter').item.json._originalJobs || [];

let keepIds = null;
if (!resp.error) {
  try {
    const raw = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
    const cleaned = raw.replace(/```json|```/g, '').trim();
    keepIds = JSON.parse(cleaned);
  } catch (e) {
    keepIds = null;
  }
}

let kept;
if (Array.isArray(keepIds)) {
  const keepSet = new Set(keepIds.map(String));
  kept = originalJobs.filter((job, idx) => keepSet.has(String(idx)));
} else {
  kept = originalJobs; // сбой/непонятный ответ по этому чанку — не фильтруем (fail open)
}

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.aiKeptJobs)) staticData.aiKeptJobs = [];
staticData.aiKeptJobs.push(...kept);

return [{ json: { chunkProcessed: true } }];

const staticData = $getWorkflowStaticData('global');
const kept = Array.isArray(staticData.aiKeptJobs) ? staticData.aiKeptJobs : [];
staticData.aiKeptJobs = []; // сброс для следующего прогона

if (kept.length === 0) {
  return [{ json: { _noNewJobs: true } }];
}
return kept.map(job => ({ json: { ...job, _noNewJobs: false } }));
